# Step 1: Aggregate Production data by machine
prod_data = sql_data.get('Production', [])
prod_agg = {}
for row in prod_data:
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine not in prod_agg:
            prod_agg[machine] = 0
        prod_agg[machine] += qty

# Step 2: Aggregate Scrap data by machine
scrap_data = sql_data.get('Scrap', [])
scrap_agg = {}
for row in scrap_data:
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine not in scrap_agg:
            scrap_agg[machine] = 0
        scrap_agg[machine] += qty

# Step 3: Calculate net production for machines existing ONLY in Production
net_production = []
for machine, prod_qty in prod_agg.items():
    if machine: # Skip NULL machines
        scrap_qty = scrap_agg.get(machine, 0)
        net_qty = prod_qty - scrap_qty
        net_production.append({'machine': machine, 'net_qty': net_qty})

out('net_production').append(net_production)
